---@class BtnFishAtlasService
local BtnFishAtlasService = Class("BtnFishAtlasService")

function BtnFishAtlasService.new(from)
    local instance = BtnFishAtlasService.New()
    instance.luaDialog = from
    for k, v in pairs(from) do
        instance[k]=v
    end

    return instance
end

function BtnFishAtlasService:UpdateInfo()
    local dojo = FishingUtils.GetFishingPlaceDojo(self.placeId)
    local num = dojo.collectNum
    local _, allFishNum = FishingUtils.GetAtlasGetNum(self.placeId)

    local num2 = checkNumber(num) / checkNumber(allFishNum) * 100
    CfUtils.FillText(self.BtnFishAtlas.transform:Find("Progress/TextNumber"), checkInt(num2).."%")
    self:SetBtnActive(true)
end

function BtnFishAtlasService:OnClick()
    if FishingUtils.IsAutoing() then
        return
    end
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFishPoolFishAltasDialog, parameters = {fishPlaceId = self.placeId}}, {
        {id = Constants.UITypeIds.UIFishPoolGoFishingDialog}
    })
end

function BtnFishAtlasService:SetBtnActive(flag)
    if flag then
        SetButtonAction(self.BtnFishAtlas, Bind(self, self.OnClick))
    else
        SetButtonAction(self.BtnFishAtlas, nil)
    end
end

return BtnFishAtlasService
